files.styles.css:
body { margin: 0; font-family: system-ui, sans-serif; }
.pricing { width: 1100px; margin: 0 auto; padding: 40px; }
.plans { display: grid; grid-template-columns: repeat(3, 340px); gap: 20px; }
.plan { border: 1px solid #ddd; border-radius: 8px; padding: 24px; }
.cta { display: inline-block; padding: 4px 8px; font-size: 12px; }

files.src/Dashboard.css:
.layout { display: flex; }
.sidebar { width: 280px; flex-shrink: 0; }
.banner { width: 100vw; padding: 16px; background: #eef2ff; }
.stats { display: grid; grid-template-columns: repeat(4, 300px); gap: 16px; }
.card { padding: 16px; border: 1px solid #e5e7eb; }

files.src/Header.css:
.header { width: 960px; margin: 0 auto; display: flex; justify-content: space-between; }
.nav { display: flex; gap: 32px; white-space: nowrap; }
.nav a { font-size: 13px; padding: 2px 4px; }
